import {escapeHTML as h,markdown} from './markdown.js';
import {STORAGE_KEY,initialState,restoreState,getDraft,exportDraft,selectActual,isTownClaim,selectedRoute,openingClaimRisk} from './model.js?v=20261015-role-switch-focus';
const $=s=>document.querySelector(s);
const icons={help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 .4c0 1.6-2.5 2-2.5 3.6"/><path d="M12 16.5v.01"/>',book:'<path d="M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H4z"/><path d="M20 3h-4a3 3 0 0 0-3 3v15a4 4 0 0 1 4-2h3z"/>',moon:'<path d="M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3"/>',dawn:'<path d="M3 17h18M5 21h14M12 3v3M4 7l2 2m12 0 2-2M6 17a6 6 0 0 1 12 0"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3 1-7a8 8 0 1 1 18-4Z"/><path d="M7 9h10M7 13h6"/>',next:'<path d="M4 12h15m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',warning:'<path d="m12 3 10 18H2Z"/><path d="M12 9v5m0 3v.1"/>',edit:'<path d="M15 4l5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14Z"/>',chevron:'<path d="m8 5 7 7-7 7"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;
let data,roles,library,byId,state,pickerMode='actual',pickerOpener=null,toastTimer,storageFailure=false,saveTimer;
const inspectedClaims={},disclosures=new Map(),controlScrolls=new Map();
const stickyLayout=new ResizeObserver(entries=>{for(const {target} of entries)document.documentElement.style.setProperty(target.matches('.site-header')?'--header-height':'--guide-nav-height',target.getBoundingClientRect().height+'px');});
const colors=role=>role.alignment.startsWith('Coven')?['#c4a2eb','#30273f']:role.alignment==='Neutral Apocalypse'?['#e3a398','#39282b']:role.alignment.startsWith('Town')?['#8bc6aa','#1e342c']:['#d8bb82','#302a20'];
function actual(){return byId.get(state.actualId);}
function base(role=actual()){return role.parentId?byId.get(role.parentId):role;}
function claimed(){return byId.get(state.claimId);}
function routeFor(role=actual()){return selectedRoute(state,role);}
function sourceLinks(urls,label='Mechanics sources'){return `<div class="strategy-sources"><span>${label}:</span> ${(urls||[]).map((url,i)=>`<a href="${h(url)}" target="_blank" rel="noopener noreferrer" aria-label="Mechanics source ${i+1}: ${h(url)}" title="${h(url)}">${i+1}</a>`).join(' ')}</div>`;}
function image(role,className=''){return `<span class="image-wrap"><img class="role-image ${className}" src="${h(role.iconUrl)}" data-fallback="${h(role.iconFallback||'')}" alt="" loading="lazy" width="44" height="44" data-role-name="${h(role.name)}"></span>`;}
function badge(role){return `<span class="badge" title="${h(role.alignment)}">${h(role.alignment_abbreviation)}</span>`;}
function fullAlignment(role){return `${h(role.alignment_abbreviation)}${role.alignment_abbreviation===role.alignment?'':` · ${h(role.alignment)}`}`;}
function isExpanded(id){return state.detail||state.expanded.includes(id);}
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageFailure=false;}catch{storageFailure=true;}updateSaveStatus();},180);}
function persistNow(){clearTimeout(saveTimer);try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageFailure=false;}catch{storageFailure=true;}updateSaveStatus();}
window.addEventListener('pagehide',()=>state&&persistNow());
function updateSaveStatus(){const el=$('#save-state');if(el)el.textContent=storageFailure?'Preferences kept in memory':'Choices saved on this browser';}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3200);}
function cardOf(role,key){return base(role).cards.find(c=>c.id.endsWith('-'+key));}
function toggleButton(id){const topic=id.startsWith('claim-example-')?'will tips':id.endsWith('-n1')?'plan reasoning':id.endsWith('-mistakes')?'all pitfalls':id.endsWith('-identity')?'role details':id.endsWith('-claims')?'claim ranking':'details',label=isExpanded(id)?'Show less':topic==='plan reasoning'?'Why this plan':topic==='all pitfalls'?'All pitfalls':'Details';return `<button class="text-button" data-action="detail" data-card="${h(id)}" aria-label="${isExpanded(id)?'Collapse':'Expand'} ${h(topic)}" aria-expanded="${isExpanded(id)}">${label}</button>`;}
const cardTitles={n1:'First night',dawn:'At dawn',disclosure:'What to say',continuation:'Next priorities',mistakes:'Avoid this',milestones:'Your subgoals',identity:'Know your role',claims:'Claim reasoning',will:'Will format & examples'};
const cardIcons={n1:'target',dawn:'dawn',disclosure:'chat',continuation:'next',milestones:'check',identity:'book',claims:'chat',will:'edit'};
function renderCard(role,key,extra='',prefix=''){
 const c=cardOf(role,key),id=prefix+c.id,expanded=isExpanded(id);
 let compact=key==='n1'&&!prefix?base(role).opening.action+'\n\n**Choose a target:** '+base(role).opening.target:c.compact;
 let expandedCopy=c.expanded;
 if(key==='dawn'&&!prefix&&role.parentId){compact=role.priorityGuide.dawn;expandedCopy=compact+'\n\n'+role.priorityGuide.goodToKnow.body;}
 if(key==='continuation'&&!prefix){const plan=routeFor(role);compact=plan.laterPriorities.map((v,i)=>`${i+1}. ${v}`).join('\n');expandedCopy=compact+'\n\n**Why this route:** '+plan.reason+'\n\n**Change the plan when:** '+plan.pivot+'\n\n**Tradeoff:** '+plan.risk+(plan.id==='default'?'\n\n'+(role.parentId?role.playbook.expanded:c.expanded):'');}
 if(key==='disclosure'&&!prefix&&(!isTownClaim(role)||role.id!==state.claimId)){
  const cover=claimed();
  compact=(isTownClaim(role)?'Temporary concealment only: reveal your real role when Town needs coordination. ':'')+'Your selected cover is **'+cover.name+' — '+cover.alignment_abbreviation+' ('+cover.alignment+')**. Use that alignment if asked. '+(cover.alignment==='Town Investigative'?'A TI story normally needs the exact role and a compatible result from D2.':'Give the full cover role and compatible history when needed.');
  expandedCopy=compact+'\n\n'+(isTownClaim(role)?'Your actual role is still **'+role.name+'**. Keep its real actions privately. Prefer alignment-only TPow when possible, and reveal the truth before Town coordination or a counterclaim requires it.':'The role-specific examples below explain starting cover options; follow the selected claim’s own obligations.\n\n'+(role.parentId?role.claimAudit.summary:c.expanded));
 }
 return `<section class="card ${extra} ${expanded?'expanded':''}" id="${h(id)}"><div class="card-heading"><h3>${icon(cardIcons[key])}${key==='dawn'&&role.id==='death'&&!prefix?'During this day':cardTitles[key]||h(c.title)}</h3>${toggleButton(id)}</div><div class="card-content">${markdown(expanded?expandedCopy:compact)}</div></section>`;
}
function renderRoutePicker(role){const routes=role.routes||[],active=routeFor(role);return `<div class="route-options choice-tray" data-scroll-key="routes-${role.id}" role="group" aria-label="Opening routes ranked by beginner usefulness">${routes.map((r,i)=>`<button class="route-choice inline-route-choice ${r.id===active.id?'chosen':''}" data-action="select-route" data-route="${h(r.id)}" aria-label="Route ${i+1}: ${h(r.label)}${i===0?' (recommended)':''}" aria-pressed="${r.id===active.id}" title="${i+1}. ${h(r.label)} — ${h(r.when)}"><span class="route-number">${i+1}</span><span class="route-name">${i===0?'<small>Recommended</small>':''}${h(r.label)}</span></button>`).join('')}</div>`;}

function renderMustKnow(role){const c=cardOf(role,'mistakes'),note=role.priorityGuide.mustKnow,expanded=isExpanded(c.id);return `<aside class="must-know" id="${c.id}" aria-labelledby="must-know-title"><div class="card-heading"><span class="eyebrow">${icon('warning')}Must know</span>${toggleButton(c.id)}</div><h4 id="must-know-title">${h(note.title)}</h4><p>${h(note.body)}</p>${expanded?`<div class="card-content full-pitfalls">${markdown(role.parentId?role.notes: c.expanded)}${sourceLinks(role.priorityGuide.sourceUrls)}</div>`:''}</aside>`;}
function renderOpeningClaimWarning(role){const risk=openingClaimRisk(role,claimed());return risk?`<aside class="opening-cover-warning" aria-labelledby="opening-cover-title"><span class="eyebrow">Before your N1 action · Claiming ${h(claimed().name)}</span><h3 id="opening-cover-title">${h(risk.title)}</h3><p>${h(risk.body)}</p></aside>`:'';}
function renderDefaultPlay(role){const c=cardOf(role,'n1'),p=routeFor(role),expanded=isExpanded(c.id),rank=(role.routes||[]).findIndex(r=>r.id===p.id)+1;return `<section class="card first-card recommended-play ${expanded?'expanded':''}" id="${c.id}"><div class="card-heading"><span class="eyebrow">${p.id==='default'?(role.parentId?'YOUR PLAN NOW':'YOUR OPENING PLAN'):'ALTERNATIVE ROUTE · '+rank}</span>${toggleButton(c.id)}</div>${renderOpeningClaimWarning(role)}<h3 class="recommendation-title">${h(p.headline)}</h3>${p.id!=='default'?`<p class="route-condition"><strong>Use this route when:</strong> ${h(p.when)}</p>`:''}<p class="recommended-action">${h(p.action)}</p>${renderMustKnow(role)}<div class="card-content plan-targeting"><p><strong>Who to choose:</strong> ${h(p.targetRule)}</p><p class="pivot-note"><strong>Change the plan when:</strong> ${h(p.pivot)}</p></div>${role.parentId?'':`<p class="modifier-note"><strong>N1 setup:</strong> Grace Period disables protective abilities, but some other roles can still act. Check both your real ability and whether your claimed role could explain the visit; this is not a blanket instruction to skip N1.</p>`}${expanded?`<div class="card-content plan-reasoning"><p><strong>Best when:</strong> ${h(p.when)}</p><p><strong>Why choose it:</strong> ${h(p.reason)}</p><p><strong>Main tradeoff:</strong> ${h(p.risk)}</p>${(p.id==='default'?markdown(role.playbook.expanded):'')}${sourceLinks([...new Set([...p.sourceUrls,'https://www.townofsalem.io/town-of-salem-2-bug-fixes-patch-notes-r1-5-01/','https://www.townofsalem.io/town-of-salem-2-updates-and-bug-fixes-patch-notes-r1-5-03/'])])}</div>`:`<p class="plan-tradeoff"><strong>Tradeoff:</strong> ${h(p.risk)}</p>`}<div class="route-heading"><span class="eyebrow">${role.parentId?'Compare current plans':'Compare opening routes'}</span>${renderRoutePicker(role)}</div><p class="recommendation-basis">Beginner priority order · Choose an alternative when its condition fits.</p></section>`;}
function renderGoodToKnow(role){const note=role.priorityGuide.goodToKnow,facts=role.studyGuide.facts;return `<aside class="good-to-know card" id="good-to-know" tabindex="-1" aria-labelledby="good-to-know-title"><span class="eyebrow">Good to know</span><h3 id="good-to-know-title">${h(note.title)}</h3><p>${h(note.body)}</p>${facts?`<div class="quick-facts"><h4>Ability at a glance</h4><dl>${facts.abilities.length?facts.abilities.map(a=>`<div><dt>${h(a.name)}</dt><dd>${h(a.phase)} <span>· ${h(a.uses.startsWith('No fixed charge limit')?a.uses.replace('No fixed charge limit','No charge limit'):/^\d+$/.test(a.uses)?a.uses+' use'+(a.uses==='1'?'':'s'):a.uses)}</span></dd></div>`).join(''):'<div><dt>Active ability</dt><dd>None</dd></div>'}</dl><p class="facts-note">Timing, cooldowns and target restrictions still apply.</p></div>`:`<p class="facts-note">Current transformed state · Use this plan instead of the earlier ${h(base(role).name)} opening.</p>`}<a class="reference-link" href="${h(role.studyGuide.sourceUrls[1])}" target="_blank" rel="noopener noreferrer">Reviewed mechanics ${icon('next')}</a></aside>`;}
function renderPageNav(){return `<nav class="page-nav" aria-label="Guide sections">${[['strategy','1','Play'],['good-to-know','2','Good to know'],['claims','3','Claims'],['will-examples','4','Will example']].map(([target,num,label])=>`<button data-action="jump-section" data-target="${target}"><span>${num}</span>${label}</button>`).join('')}</nav>`;}
function renderGoals(role){const c=cardOf(role,'milestones'),expanded=isExpanded(c.id),route=routeFor(role),goals=route.goals,checked=route.id==='default'?state.goals[role.id]||[]:state.routeGoals?.[role.id]?.[route.id]||[];return `<section class="card goals-card ${expanded?'expanded':''}" id="${c.id}"><div class="card-heading"><h3>${icon('check')}Your subgoals</h3>${toggleButton(c.id)}</div><ul class="goals-list">${goals.map((g,i)=>`<li><label><input type="checkbox" data-goal="${i}" data-goal-route="${h(route.id)}" ${checked.includes(i)?'checked':''}><span>${h(g)}</span></label></li>`).join('')}</ul>${expanded?`<div class="card-content more-guidance"><p>These checkpoints follow your selected opening route. A route choice does not change your role or public claim.</p></div>`:'<p class="goals-footer">Checkpoints follow this route. A reasoned hold counts.</p>'}</section>`;}

function renderRoleGroups(){
 const group=r=>r.alignment.startsWith('Town')?'Town':r.alignment.startsWith('Coven')?'Coven':'Neutral';
 const current=group(actual());
 return `<nav class="role-quick-nav" aria-label="Quick role selection"><span class="eyebrow">CHOOSE YOUR ROLE</span><div class="role-group-buttons">${[['all','All roles'],['Town','Town'],['Coven','Coven'],['Neutral','Neutral']].map(([faction,label])=>{const count=library.filter(r=>faction==='all'||group(r)===faction).length;return `<button class="role-group-button ${faction===current?'current-group':''}" data-action="choose-group" data-faction="${faction}" aria-label="Choose ${label.toLowerCase()} (${count} roles and states)" aria-haspopup="dialog" aria-expanded="false"><span class="faction-dot ${faction.toLowerCase()}" aria-hidden="true"></span>${label}<span class="role-group-count">${count}</span></button>`;}).join('')}</div></nav>`;
}
function renderHero(){const role=actual(),b=base(role),c=cardOf(role,'identity'),expanded=isExpanded(c.id);return `<section class="hero" aria-labelledby="role-title">${image(role,'hero-art')}<div><span class="eyebrow">YOUR ACTUAL ROLE${role.parentId?' · TRANSFORMED':''}</span><div class="role-title-row"><h1 id="role-title">${h(role.name)}</h1><button class="role-help button" data-action="study-role" aria-label="Study ${h(role.name)}: full role guide" aria-haspopup="dialog" title="Study this role">${icon('book')}<span>Role guide</span></button></div><div class="role-meta">${badge(role)}<span>${h(role.alignment)}</span>${role.alignment.endsWith('Outlier')?'<span class="badge neutral">Setup-dependent</span>':''}</div><div class="role-description ${expanded?'card-content':''}" id="${c.id}">${markdown(role.parentId?(expanded?role.description+'\n\n'+role.playbook.expanded:role.description):expanded?c.expanded:c.compact.replace(/ (?:TI|TP|TK|TS|TPow|CPow|CK|CD|CU|NA|NE|NK) — [^.]+\.$/,''))}${toggleButton(c.id)}</div><p class="public-story">Public claim: <strong>${h(claimed().name)} · ${h(claimed().alignment_abbreviation)}</strong><button class="text-button" data-action="jump-section" data-target="claims">Review claim ${icon('next')}</button></p></div></section>${role.parentId?`<div class="state-callout">Transformed from <strong>${h(b.name)}</strong>. The plan below follows <strong>${h(role.name)}</strong>; earlier mechanics remain in the full role guide.</div>`:''}`;}
function renderClaimBasics(role,{example=false,key='card'}={}){const p=role.claimProfile;return `<details class="claim-basics" data-claim-basics="${role.id}" data-disclosure="basics-${actual().id}-${key}-${role.id}" ${state.detail?'open':''}><summary>${icon('book')}<span>What does ${h(role.name)} do?</span>${icon('chevron')}</summary><div class="claim-basics-body"><p>${h(p.plainAbility)}</p><p><strong>By claiming it, you mean:</strong> ${h(p.claimMeaning)}</p>${example&&p.simpleExample?`<p class="claim-simple-example"><strong>For example:</strong> ${h(p.simpleExample)}</p>`:''}</div></details>`;}
function renderClaimSetupWarning(profile){return profile.setupWarning?`<p class="claim-setup-warning"><strong>Setup check:</strong> ${h(profile.setupWarning)}</p>`:'';}
function renderClaimOption(option,rank,{preview=false}={}){const role=actual(),cover=byId.get(option.roleId),truthful=isTownClaim(role)&&role.id===cover.id;return `<article class="claim-option ${state.claimId===cover.id?'selected':''} ${preview?'claim-preview':''}" data-claim-option="${cover.id}"><div class="claim-option-top"><span class="claim-rank">${rank?rank:'—'}</span>${image(cover)}<div class="claim-option-info"><h3>${h(cover.name)} ${badge(cover)}</h3><span class="fit-label">${h(option.tag)}</span></div><button class="button use-claim" data-action="use-claim" data-role="${cover.id}" aria-pressed="${state.claimId===cover.id}">${state.claimId===cover.id?'Selected':'Use claim'}</button></div><div class="claim-upkeep">${h(cover.claimProfile.effort)}</div>${renderClaimSetupWarning(cover.claimProfile)}<p class="claim-strategy-intro"><strong>${truthful?'How to explain your real role':'What overlaps with '+h(role.name)}:</strong> ${h(option.why)}</p><ul class="claim-strategy">${option.strategy.map(t=>`<li>${h(t)}</li>`).join('')}</ul><p class="claim-when"><strong>${truthful&&role.claimRecommendation?'Recommended disclosure':'Best when'}:</strong> ${h(option.bestWhen)}</p><p class="exposure"><strong>${truthful&&role.claimRecommendation?'When to disclose or act':truthful?'Limits to explain':'What can expose it'}:</strong> ${h(option.exposure)}</p>${renderClaimBasics(cover)}<details class="claim-payoff" data-disclosure="payoff-${role.id}-${cover.id}"><summary>Payoff, posting & sources</summary><p>${h(cover.claimProfile.payoff)}</p><p><strong>Posting:</strong> ${h(cover.claimProfile.posting)}</p>${sourceLinks(option.sourceUrls)}</details></article>`;}
function manualClaimOption(role,cover){return {roleId:cover.id,tag:'Unranked selection · check the fit',why:'This is selectable, but is not one of the researched ranked fits for '+role.name+'.',strategy:[cover.claimProfile.claimMeaning,'Compare your real destinations with the claimed action before recording a target. A matching visit alone supplies no claimed result.','Check the chosen role’s posting and demonstration obligations below; preserve the same history if questioned.'],bestWhen:'Only when you can give a concrete match-specific reason for this choice.',exposure:cover.claimProfile.exposure,sourceUrls:[base(role).source_url,cover.source_url]};}
function renderClaims(){const role=actual(),cover=claimed(),c=cardOf(role,'claims'),options=(role.claimOptions||[]).filter(o=>isTownClaim(byId.get(o.roleId))),primary=options.slice(0,role.claimRecommendation?1:2),others=options.slice(primary.length),previewId=Object.hasOwn(inspectedClaims,role.id)?(others.some(o=>o.roleId===inspectedClaims[role.id])?inspectedClaims[role.id]:null):(others.find(o=>o.roleId===cover.id)?.roleId||null),preview=others.find(o=>o.roleId===previewId),unranked=!options.some(o=>o.roleId===cover.id),expanded=isExpanded(c.id);return `<section id="claims"><div class="section-head claims-heading"><h2>${role.alignment==='Town Power'?'Your real role & optional covers':isTownClaim(role)?'Explain your role clearly':'Choose a claim you can maintain'}</h2><div class="claim-selector"><span class="eyebrow">CLAIMING AS</span><button class="button" data-action="choose-claim">${image(cover,'tiny-role')} ${h(cover.name)} ${badge(cover)} ${icon('chevron')}</button></div></div><p class="claims-help">${role.claimRecommendation?h(role.claimRecommendation.opening):isTownClaim(role)?'Use your real role and truthful results. The normal Town route does not require a false claim.':'Ranked for a beginner: start with these two, then explore conditional alternatives.'} All 29 Town roles remain selectable.</p><div class="claim-grid ${primary.length===1?'one-option':''}">${primary.map((o,i)=>renderClaimOption(o,i+1)).join('')}</div>${others.length?`<section class="other-claims" id="other-claims" aria-label="Lower-priority claim comparisons"><div class="inline-claim-header"><div class="other-claims-label"><span>${role.claimRecommendation?'Situational covers':'Other claims,'}</span><small>${role.claimRecommendation?'optional · not the default':'ranked'} · ${others.length} to explore</small></div><div class="claim-icon-list choice-tray" data-scroll-key="claims-${role.id}" role="group" aria-label="Lower-priority claims in ranked order">${others.map((o,i)=>{const r=byId.get(o.roleId),selected=previewId===r.id;return `<button class="claim-icon-choice inline-claim-choice ${selected?'chosen':''}" data-action="inspect-claim" data-role="${r.id}" aria-pressed="${selected}" aria-expanded="${selected}" aria-controls="claim-preview" aria-label="Compare ${i+primary.length+1}. ${h(r.name)} (${h(r.alignment_abbreviation)})" title="${i+primary.length+1}. ${h(r.name)}: ${h(o.tag)}"><span class="rank-number">${i+primary.length+1}</span>${image(r)}<span class="choice-name">${h(r.name)}</span></button>`;}).join('')}</div></div><div id="claim-preview" ${preview?'':'hidden'}>${preview?renderClaimOption(preview,options.indexOf(preview)+1,{preview:true}):''}</div></section>`:''}${unranked?`<div class="unranked-claim">${renderClaimOption(manualClaimOption(role,cover),0,{preview:true})}</div>`:''}<div class="claim-advice"><strong>My take:</strong> ${h(role.claimAudit.summary)}</div><div class="claim-explainer"><div class="card-heading"><span class="eyebrow">WHY THIS ORDER?</span>${toggleButton(c.id)}</div>${expanded?`<div class="card-content"><p>${role.claimRecommendation?h(role.claimRecommendation.coverWhen)+' ':''}Order favors a manageable opening, useful overlap, and a clear explanation of what can fail. It is editorial strategy, not a measured win-rate ranking. An alternative can move ahead when its stated condition applies. Jester ranks seek a qualifying hanging; most other opposing roles need survival.</p>${sourceLinks(options.flatMap(o=>o.sourceUrls||[]).filter((u,i,a)=>a.indexOf(u)===i))}</div>`:''}</div><details class="cover-guide" id="cover-guide" data-disclosure="cover-${role.id}"><summary>Expand ${h(cover.name)} mechanics <span class="muted">· ${fullAlignment(cover)}</span></summary><div class="cover-content"><p class="cover-banner">CLAIMED ROLE GUIDE · Your actual role is still ${h(role.name)}.</p><div class="support-grid">${['n1','dawn','disclosure','continuation','mistakes','will'].map(k=>renderCard(cover,k,'','cover-')).join('')}</div></div></details></section>`;}

function renderExample(){const role=claimed(),profile=role.claimProfile,id='claim-example-'+role.id,expanded=isExpanded(id),truthful=state.actualId===state.claimId&&base(actual()).alignment.startsWith('Town');return `<section class="example-section" id="will-examples" aria-labelledby="example-heading"><div class="section-head"><h2 id="example-heading">Example will · ${h(role.name)} ${badge(role)}</h2>${toggleButton(id)}</div><p class="claims-help">${truthful?'Format your real results this way.':'A format lesson for the role you are claiming; it does not create that ability or its results.'} Sample numbers and outcomes are illustrative.</p>${renderClaimSetupWarning(profile)}<div class="example-grid"><div><div class="example-code-heading"><div class="copy-actions"><button class="button" data-action="copy-blank">Copy blank format</button><button class="button copy-primary" data-action="copy-example">${icon('copy')}Copy example</button></div></div><pre class="example-code" id="claim-example">${h(profile.example)}</pre><p class="copy-fallback" id="copy-fallback" hidden>Clipboard access is unavailable. Select the example text above to copy it.</p><p class="example-posting"><strong>When to claim or post:</strong> ${h(profile.posting)}</p></div><div class="example-tips"><h3>How to keep this history believable</h3><ul>${profile.willGuidance.map(t=>`<li>${h(t)}</li>`).join('')}</ul></div></div>${expanded?`<div class="card-content example-expanded"><p><strong>Effort:</strong> ${h(profile.effort)}. ${h(profile.payoff)}</p><p><strong>Exposure:</strong> ${h(profile.exposure)}</p>${markdown(profile.expanded)}<p>${h(role.template.notes)}</p></div>`:''}</section>`;}
function renderLegacyNotes(){const logs=[];for(const ns of ['public','private'])for(const [id,draft]of Object.entries(state.drafts[ns]||{})){if(!byId.has(id)||(!draft.entries.length&&!draft.title))continue;logs.push(`<details><summary>${ns==='private'?'Private actual notes':'Previous public draft'} · ${h(byId.get(id).name)}</summary><pre class="example-code">${h(exportDraft(state,ns,byId.get(id)).text)}</pre></details>`);}return logs.length?`<details class="legacy-notes"><summary>Previous saved notes · read only</summary><p>The editor has been replaced by examples. Your old notes are retained for reference and stay separate from copied examples.</p>${logs.join('')}</details>`:'';}
function renderStrategy(){const role=actual();return `<section id="strategy" aria-label="Quick strategy" tabindex="-1"><div class="section-head"><h2>Your next good decision</h2><div class="phase-tabs" aria-label="Focus a phase">${[['n1',role.parentId?'Current plan':'First night'],['day',role.parentId?'Daytime':'Day 2'],['later','Later']].map(([id,label])=>`<button data-action="phase" data-phase="${id}" aria-pressed="${state.phase===id}">${label}</button>`).join('')}</div></div><div class="strategy-top">${renderDefaultPlay(role)}${renderGoodToKnow(role)}</div><div class="phase-sequence-heading"><span class="eyebrow">Then follow the match</span><span>Read the result → explain it → choose the next action</span></div><div class="support-grid observations-grid">${renderCard(role,'dawn',state.phase==='day'?'active-phase':'')}${renderCard(role,'disclosure',state.phase==='day'?'active-phase':'')}</div><div class="strategy-later"><div class="ranked-priorities">${renderCard(role,'continuation',state.phase==='later'?'active-phase':'')}</div>${renderGoals(role)}</div></section>`;}
function render(resetDisclosures=false){
 const role=actual(),[accent,tint]=colors(role);document.documentElement.style.setProperty('--accent',state.theme==='light'?({Town:'#31664e',Coven:'#794ca0',Apocalypse:'#a14d43',Neutral:'#896730'}[base(role).faction]||'#896730'):accent);document.documentElement.style.setProperty('--accent-bg',state.theme==='light'?({Town:'#e4eee5',Coven:'#f0e7f7',Apocalypse:'#f6e6e1',Neutral:'#f1e9d7'}[base(role).faction]||'#f1e9d7'):tint);
 document.documentElement.dataset.theme=state.theme;
 $('#detail-toggle').innerHTML=icon('book')+(state.detail?'Less detail':'More detail');$('#detail-toggle').setAttribute('aria-expanded',String(state.detail));
 $('#theme-toggle').innerHTML=icon(state.theme==='dark'?'sun':'moon');$('#theme-toggle').setAttribute('aria-label',state.theme==='dark'?'Switch to light theme':'Switch to dark theme');
 document.querySelectorAll('[data-scroll-key]').forEach(el=>controlScrolls.set(el.dataset.scrollKey,el.scrollTop));
 if(resetDisclosures)disclosures.clear();else document.querySelectorAll('[data-disclosure]').forEach(el=>disclosures.set(el.dataset.disclosure,el.open));
 if($('.page-nav'))stickyLayout.unobserve($('.page-nav'));
 $('#app').innerHTML=renderRoleGroups()+renderHero()+renderPageNav()+renderStrategy()+renderClaims()+renderExample()+renderLegacyNotes()+`<p class="source-footnote">Mechanics checked 15 Oct 2026 · Default plays, priority order, and claim assessments are editorial recommendations. <button class="text-button" data-action="sources">Review sources</button></p>`;
 stickyLayout.observe($('.page-nav'));
 document.querySelectorAll('[data-disclosure]').forEach(el=>{if(disclosures.has(el.dataset.disclosure))el.open=disclosures.get(el.dataset.disclosure);});
 document.querySelectorAll('[data-scroll-key]').forEach(el=>{el.scrollTop=controlScrolls.get(el.dataset.scrollKey)||0;});
}
function pickerFilter(){const query=$('#role-search').value.trim().toLowerCase(),faction=$('#faction-filter').value,alignment=$('#alignment-filter').value;const current=pickerMode==='actual'?state.actualId:state.claimId;const results=library.filter(r=>{
 if(pickerMode==='claim'&&!isTownClaim(r))return false;
 const b=base(r);const neutral=!b.alignment.startsWith('Town')&&!b.alignment.startsWith('Coven');
 return (faction==='all'||(faction==='Neutral'?neutral:b.faction===faction))&&(alignment==='all'||r.alignment===alignment)&&`${r.name} ${r.alignment} ${r.alignment_abbreviation} ${(r.aliases||[]).join(' ')} ${r.parentId?base(r).name:''}`.toLowerCase().includes(query);
 });
 const available=roles.filter(r=>(pickerMode!=='claim'||isTownClaim(r))&&(faction==='all'||(faction==='Neutral'?!r.alignment.startsWith('Town')&&!r.alignment.startsWith('Coven'):r.faction===faction)));
 const alignments=[...new Set(available.map(r=>r.alignment))];
 $('#alignment-shortcuts').innerHTML=[['all','All'],...alignments.map(a=>[a,available.find(r=>r.alignment===a).alignment_abbreviation])].map(([value,label])=>`<button class="button alignment-shortcut" data-action="filter-alignment" data-alignment="${h(value)}" aria-pressed="${alignment===value}" title="${h(value==='all'?'All alignments':value)}">${h(label)}</button>`).join('');
 $('#picker-count').textContent=`${results.length} results`;
 $('#picker-results').innerHTML=results.length?results.map(r=>`<button class="role-result ${current===r.id?'selected':''}" data-action="pick-role" data-role="${r.id}" aria-pressed="${current===r.id}">${image(r)}<span><strong>${h(r.name)}</strong><small>${r.parentId?h(base(r).name)+' transformation':fullAlignment(r)}${r.alignment.endsWith('Outlier')?' · Setup-dependent':''}</small></span></button>`).join(''):'<div class="picker-empty">No roles match. Clear the search or filters to see the available roles.</div>';
 $('#recent-roles').innerHTML=!query&&faction==='all'&&alignment==='all'&&state.recent.length?`<div class="recent-section">RECENT ROLES<div class="recent-list">${state.recent.map(id=>byId.get(id)).filter(r=>pickerMode==='actual'||isTownClaim(r)).map(r=>`<button class="button" data-action="pick-role" data-role="${r.id}">${image(r)}${h(r.name)}</button>`).join('')}</div></div>`:'';
}
function openPicker(mode,opener,faction='all'){pickerMode=mode;pickerOpener=opener;const claim=mode==='claim';$('#picker-title').textContent=claim?'Choose your Town claim':'Choose your actual role';$('#picker-help').textContent=claim?'29 Town roles. Choose a public story you can maintain; your actual role stays separate.':'Changing your actual role also selects its recommended public claim.';$('#role-search').value='';$('#faction-filter').hidden=claim;$('#faction-filter').value=claim?'Town':faction;const available=claim?roles.filter(isTownClaim):roles;$('#alignment-filter').innerHTML='<option value="all">All alignments</option>'+[...new Set(available.map(r=>r.alignment))].map(a=>`<option value="${h(a)}">${h(available.find(r=>r.alignment===a).alignment_abbreviation)} · ${h(a)}</option>`).join('');$('#alignment-filter').value='all';pickerFilter();$('#role-picker').showModal();opener?.setAttribute('aria-expanded','true');$('#role-search').focus({preventScroll:true});$('#role-search').select();}

let studyOpener=null;
function openStudy(opener){const role=actual(),g=role.studyGuide;studyOpener=opener;$('#study-title').textContent=role.name+' · Study guide';$('#study-content').innerHTML=`<p class="study-alignment">${fullAlignment(role)}</p><section class="study-summary"><h3>At a glance</h3>${markdown(g.summary)}</section>${renderOpeningClaimWarning(role)}${g.facts?`<section class="study-facts"><h3>Ability reference</h3><dl><dt>Listed attack</dt><dd>${h(g.facts.attack)}</dd><dt>Listed defense</dt><dd>${h(g.facts.defense)}</dd></dl><p class="muted">Base stats and conditional changes. Ability effects, protection and Necronomicon attacks can differ; read the rules below.</p>${g.facts.abilities.length?`<div class="table-wrap"><table><thead><tr><th scope="col">Ability</th><th scope="col">Phase</th><th scope="col">Uses</th></tr></thead><tbody>${g.facts.abilities.map(a=>`<tr><th scope="row">${h(a.name)}</th><td>${h(a.phase)}</td><td>${h(a.uses)}</td></tr>`).join('')}</tbody></table></div><p class="muted">Charges do not remove preparation, cooldown, target or setup restrictions.</p>`:'<p>No active role ability.</p>'}</section>`:''}<nav class="study-toc" aria-label="Study guide sections">${g.sections.map((x,i)=>`<a href="#study-section-${i}">${h(x.title)}</a>`).join('')}</nav>${g.sections.map((x,i)=>`<section class="study-section" id="study-section-${i}" tabindex="-1"><h3>${h(x.title)}</h3>${markdown(x.markdown)}</section>`).join('')}<h3>Deeper rules, in plain language</h3><p>Expand a topic for the detailed explanation.</p>${g.details.map(x=>`<details class="study-detail"><summary>${h(x.title)}</summary>${markdown(x.markdown)}</details>`).join('')}<p class="source-footnote">Vanilla ToS2 · Normal factions · Reviewed ${h(g.reviewedOn)}. Strategy is editorial; check your current role card for setup changes.</p><div class="source-links"><a href="${h(g.sourceUrls[0])}" target="_blank" rel="noopener noreferrer">Full wiki article</a><a href="${h(g.sourceUrls[1])}" target="_blank" rel="noopener noreferrer">Reviewed revision</a></div>`;$('#role-study').showModal();$('#role-study').scrollTop=0;$('#study-title').focus({preventScroll:true});}
function closePicker(){if($('#role-picker').open)$('#role-picker').close();}
function closeOnBackdrop(event){const dialog=event.currentTarget;if(event.target!==dialog)return;const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}
function revealChosenClaim(){const index=actual().claimOptions.findIndex(o=>o.roleId===state.claimId);if(index>=(actual().claimRecommendation?1:2))inspectedClaims[actual().id]=state.claimId;}
function useClaim(id){if(!isTownClaim(byId.get(id)))return;state.claimId=id;state.deliberateClaim=true;inspectedClaims[actual().id]=id;save();render();revealChosenClaim();}
function expandCard(id){if(state.detail){state.detail=false;state.expanded=[...document.querySelectorAll('[data-card]')].map(e=>e.dataset.card).filter(x=>x!==id);}else if(state.expanded.includes(id))state.expanded=state.expanded.filter(x=>x!==id);else state.expanded.push(id);save();render();const button=[...document.querySelectorAll('[data-card]')].find(e=>e.dataset.card===id);button?.focus({preventScroll:true});}
function showReference(kind){const area=$('#reference-area');if(!area.hidden&&area.dataset.kind===kind){area.hidden=true;return;}area.dataset.kind=kind;area.hidden=false;
 if(kind==='glossary')area.innerHTML=`<div class="card-heading"><h2>Terms, without the guesswork</h2><button class="text-button" data-action="close-reference">Close</button></div><div class="card-content">${markdown(data.glossary.markdown)}</div>`;
 else {const r=base();area.innerHTML=`<div class="card-heading"><h2>Sources & game artwork</h2><button class="text-button" data-action="close-reference">Close</button></div><div class="card-content"><p>Mechanics checked <strong>15 October 2026</strong> for vanilla text chat with normal factions. Targeting, subgoals, and claim fits are strategic suggestions, not measured success rates. No live-client test is claimed.</p><div class="source-links"><a target="_blank" rel="noopener noreferrer" href="${h(r.source_url)}">${h(r.name)} mechanics</a><a target="_blank" rel="noopener noreferrer" href="${h(r.source_revision_url)}">Reviewed revision</a><a target="_blank" rel="noopener noreferrer" href="${h(actual().iconSource||r.iconSource)}">This role’s artwork source</a><a target="_blank" rel="noopener noreferrer" href="${h(data.sourceSummary.iconRepository)}">Vanilla PNG collection</a></div><p>Town of Salem 2 role art belongs to its respective rights holders. The interface uses actual Vanilla role PNGs from a pinned Fancy UI asset revision, with source-linked original artwork for Oracle, Catalyst, and Cultist. Oracle’s original PNG is bundled with this site for reliable loading. Pilgrim and Covenite use their faction icons. Game artwork is not generated. Role labels remain usable if an image fails.</p><details><summary>Source disagreements & limits</summary>${markdown(data.sourceSummary.uncertaintiesMarkdown)}</details></div>`;}
 area.scrollIntoView({behavior:'smooth',block:'start'});area.focus({preventScroll:true});}
async function copyExample(blank=false){const p=claimed().claimProfile,text=blank?p.blank:p.example;try{await navigator.clipboard.writeText(text);toast(blank?'Blank format copied — fill in your own history':'Example copied — replace the sample numbers and results');}catch{$('#copy-fallback').hidden=false;const el=$('#claim-example');el.textContent=text;const selection=window.getSelection(),range=document.createRange();range.selectNodeContents(el);selection.removeAllRanges();selection.addRange(range);el.scrollIntoView({block:'nearest'});toast('Select the example text to copy it');}}
async function handleClick(event){const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
 if(action==='study-role')openStudy(button);
 else if(action==='jump-section'){const target=document.getElementById(button.dataset.target);if(!target)return;target.setAttribute('tabindex','-1');target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});target.focus({preventScroll:true});}
 else if(action==='close-study')$('#role-study').close();
 else if(action==='filter-alignment'){$('#alignment-filter').value=button.dataset.alignment;pickerFilter();$('#role-search').focus({preventScroll:true});$('#role-search').select();}
 else if(action==='choose-actual')openPicker('actual',button);
 else if(action==='choose-group')openPicker('actual',button,button.dataset.faction);
 else if(action==='choose-claim')openPicker('claim',button);
 else if(action==='close-picker')closePicker();
 else if(action==='pick-role'){const r=byId.get(button.dataset.role);if(!r||(pickerMode==='claim'&&!isTownClaim(r)))return;if(pickerMode==='actual'){if(state.actualId!==r.id)delete inspectedClaims[r.id];selectActual(state,r,library);history.replaceState(null,'','#'+r.id);state.expanded=[];}else{state.claimId=r.id;state.deliberateClaim=true;inspectedClaims[actual().id]=r.id;}const focusSelector=pickerMode==='actual'&&pickerOpener?.dataset.faction?`[data-action="choose-group"][data-faction="${pickerOpener.dataset.faction}"]`:(pickerMode==='actual'?'[data-action="choose-group"][data-faction="all"]':'[data-action="choose-claim"]');closePicker();save();render();if(pickerMode==='claim')revealChosenClaim();document.querySelector(focusSelector)?.focus({preventScroll:true});toast(`${r.name} ${pickerMode==='actual'?'guide opened':'selected as public claim'}`);}
 else if(action==='select-route'){const route=actual().routes.find(r=>r.id===button.dataset.route);if(!route)return;state.routeChoices[actual().id]=route.id;save();render();document.querySelector(`[data-action="select-route"][data-route="${route.id}"]`)?.focus({preventScroll:true});}
 else if(action==='inspect-claim'){if(!actual().claimOptions.some(o=>o.roleId===button.dataset.role))return;inspectedClaims[actual().id]=button.getAttribute('aria-expanded')==='true'?null:button.dataset.role;render();document.querySelector(`[data-action="inspect-claim"][data-role="${button.dataset.role}"]`)?.focus({preventScroll:true});}
 else if(action==='use-claim'){useClaim(button.dataset.role);document.querySelector(`[data-action="use-claim"][data-role="${button.dataset.role}"]`)?.focus({preventScroll:true});}
 else if(action==='detail')expandCard(button.dataset.card);
 else if(action==='phase'){state.phase=button.dataset.phase;save();render();const key=state.phase==='day'?'dawn':state.phase==='later'?'continuation':'n1';document.getElementById(cardOf(actual(),key).id)?.scrollIntoView({behavior:'smooth',block:'nearest'});document.querySelector(`[data-phase="${state.phase}"]`)?.focus({preventScroll:true});}
 else if(action==='toggle-setup'){const note=$('#setup-note');note.hidden=!note.hidden;button.setAttribute('aria-expanded',String(!note.hidden));}
 else if(action==='copy-example')await copyExample(false);
 else if(action==='copy-blank')await copyExample(true);
 else if(action==='open-reset')$('#reset-dialog').showModal();
 else if(action==='cancel-reset')$('#reset-dialog').close();
 else if(action==='confirm-reset'){const preferences={theme:state.theme,detail:state.detail};state={...initialState(),...preferences};history.replaceState(null,'',location.pathname+location.search);disclosures.clear();Object.keys(inspectedClaims).forEach(k=>delete inspectedClaims[k]);persistNow();$('#reset-dialog').close();render(true);toast('Fresh match started');}
 else if(action==='glossary'||action==='sources')showReference(action);
 else if(action==='close-reference'){$('#reference-area').hidden=true;document.querySelector(`[data-action="${$('#reference-area').dataset.kind}"]`)?.focus();}
}
function handleInput(event){if(event.target.id==='role-search')pickerFilter();}
function handleChange(event){const el=event.target;if(el.id==='faction-filter'||el.id==='alignment-filter'){if(el.id==='faction-filter')$('#alignment-filter').value='all';pickerFilter();return;}if(el.dataset.goal!==undefined){const route=routeFor(),store=route.id==='default'?state.goals:(state.routeGoals[state.actualId]||={}),key=route.id==='default'?state.actualId:route.id,goals=new Set(store[key]||[]);el.checked?goals.add(Number(el.dataset.goal)):goals.delete(Number(el.dataset.goal));store[key]=[...goals];save();}}
document.addEventListener('error',event=>{const img=event.target;if(!(img instanceof HTMLImageElement))return;const fallback=img.dataset.fallback;if(fallback&&img.src!==fallback){img.src=fallback;img.dataset.fallback='';return;}const replacement=document.createElement('span');replacement.className='image-fallback';replacement.setAttribute('aria-hidden','true');replacement.textContent=(img.dataset.roleName||'?').slice(0,2);img.replaceWith(replacement);},true);
async function boot(){try{
 const response=await fetch('./data/roles.json?v=20261015-medusa-grace');if(!response.ok)throw new Error('Role library could not load');data=await response.json();roles=data.roles;library=[...roles,...data.states].sort((a,b)=>a.name.localeCompare(b.name));byId=new Map(library.map(r=>[r.id,r]));
 let raw;try{raw=localStorage.getItem(STORAGE_KEY);}catch{storageFailure=true;}
 let recovered=false;try{state=restoreState(raw,library);}catch{state=initialState();recovered=true;try{localStorage.setItem(STORAGE_KEY+':recovery',raw);localStorage.removeItem(STORAGE_KEY);}catch{storageFailure=true;}}
 if(!state.deliberateClaim){const previous=getDraft(state,'public',state.claimId);if(!previous.entries.length&&!previous.title)state.claimId=actual().preferredClaimId||state.claimId;}
 const hash=decodeURIComponent(location.hash.slice(1));if(byId.has(hash)){selectActual(state,byId.get(hash),library);}

 window.addEventListener('hashchange',()=>{const r=byId.get(decodeURIComponent(location.hash.slice(1)));if(r&&r.id!==state.actualId){delete inspectedClaims[r.id];selectActual(state,r,library);state.expanded=[];save();render();}});
 render();document.addEventListener('click',handleClick);document.addEventListener('input',handleInput);document.addEventListener('change',handleChange);
 stickyLayout.observe($('.site-header'));
 $('#detail-toggle').addEventListener('click',()=>{state.detail=!state.detail;state.expanded=[];save();render(true);$('#detail-toggle').focus({preventScroll:true});});
 $('#theme-toggle').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';save();render();$('#theme-toggle').focus({preventScroll:true});});
 $('#new-match').addEventListener('click',()=>$('#reset-dialog').showModal());
 $('#clear-filters').addEventListener('click',()=>{$('#role-search').value='';$('#faction-filter').value=pickerMode==='claim'?'Town':'all';$('#alignment-filter').value='all';pickerFilter();$('#role-search').focus({preventScroll:true});$('#role-search').select();});
 document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',closeOnBackdrop));
 $('#role-study').addEventListener('close',()=>studyOpener?.isConnected&&studyOpener.focus({preventScroll:true}));
 $('#study-content').addEventListener('click',e=>{const link=e.target.closest('a[href^="#study-section-"]');if(link){e.preventDefault();const section=document.getElementById(link.getAttribute('href').slice(1));section?.scrollIntoView({block:'start'});section?.focus({preventScroll:true});}});
 $('#role-picker').addEventListener('close',()=>{if(pickerOpener?.isConnected){pickerOpener.setAttribute('aria-expanded','false');pickerOpener.focus();}});
 $('#role-picker').addEventListener('keydown',e=>{const buttons=[...$('#picker-results').querySelectorAll('button')];if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const index=buttons.indexOf(document.activeElement),next=e.key==='ArrowDown'?Math.min(index+1,buttons.length-1):Math.max(0,index-1);buttons[next]?.focus();}else if(e.key==='Enter'&&e.target.id==='role-search'){e.preventDefault();buttons[0]?.click();}});
 if(recovered)toast('Saved data could not load. A recovery copy was kept where storage permits.');
 }catch(error){$('#app').innerHTML='<div class="load-error notice"><strong>The role library could not load.</strong><p>Refresh the page or check your connection. Existing browser drafts have not been changed.</p><button class="button" id="reload-app">Try again</button></div>';$('#reload-app').addEventListener('click',()=>location.reload());console.error(error);}}
boot();
